-        Self(RefPtr::new(unsafe_listener))
-    }
-}
-
-impl<L: XpCom> UnsafeListener for SafeListenerWrapper<L> {
-    fn unsafe_listener(&self) -> impl Deref<Target = impl XpCom> {
